"""Genetics passages with pedigrees (Biology unit 12)."""
from passage_kit import passage, table, line, bar
from bio_kit import pedigree

P = []

# ---------------------------------------------------------------- cystic fibrosis (autosomal recessive)
cf = {"a": (1, 2, "M", "U"), "b": (1, 4, "F", "U"),
      "c": (2, 1, "M", "U"), "d": (2, 3, "F", "A"), "e": (2, 5, "M", "U"), "f": (2, 6.5, "F", "U"),
      "g": (3, 5, "F", "U"), "h": (3, 6.5, "M", "A")}
P.append(passage("bios-01", "bb", "bio", 12, "A Family With Cystic Fibrosis", [
    "Cystic fibrosis (CF) is caused by mutations in the <i>CFTR</i> gene, which encodes a chloride channel in the cells lining the lungs, pancreas and sweat glands. Without working channels, mucus becomes thick and sticky, leading to lung infections and poor digestion. A genetic counselor drew the pedigree in Figure 1 for a family in which two members have CF.",
    pedigree("Figure 1 Pedigree of a family with cystic fibrosis", cf, couples=[("a", "b"), ("e", "f")],
             families=[(("a", "b"), ["c", "d", "e"]), (("e", "f"), ["g", "h"])], w=440),
    "Neither II-4 nor anyone in her family has a history of CF. The counselor offered genetic testing for the most common CF mutation, F508del, which deletes a single phenylalanine from the protein. Results are in Table 1.",
    table("Table 1 F508del testing", ["Person", "Result"], [["II-2", "two copies of F508del"], ["II-3", "one copy of F508del"], ["II-4", "no F508del detected"], ["III-2", "one copy of F508del"]]),
    "More than 2000 different <i>CFTR</i> mutations are known. The standard test looks only for the most common ones. In people of Northern European ancestry, about 1 in 2500 babies is born with CF. The Hardy–Weinberg equations, <i>p</i> + <i>q</i> = 1 and <i>p</i><sup>2</sup> + 2<i>pq</i> + <i>q</i><sup>2</sup> = 1, relate the frequency of a recessive disease (<i>q</i><sup>2</sup>) to the frequency of carriers (2<i>pq</i>).",
    "To identify the mode of inheritance, counselors look first at whether the trait skips generations, whether both sexes are affected, and whether an affected father ever passes the trait to a son.",
    "A sweat chloride test confirms the diagnosis: CF patients have sweat chloride above 60 mmol L⁻¹, while healthy people have less than 30 mmol L⁻¹.",
], [
    dict(q="Which pattern of inheritance best fits Figure 1?", right="Autosomal recessive",
         wrong=[("Autosomal dominant", "Two unaffected parents (I-1 and I-2) had an affected child, which can't happen with a dominant allele unless there's a new mutation."),
                ("X-linked recessive", "II-2 is an affected daughter of an unaffected father. With X-linked recessive inheritance, her father would have to be affected."),
                ("Mitochondrial (maternal)", "III-2 is affected but his mother, II-4, is not. Mitochondrial traits pass from affected mothers.")],
         e=["Unaffected parents with an affected child: recessive.", "An affected daughter with an unaffected father rules out X-linked recessive, so it's autosomal."], k=4),
    dict(q="What is the probability that II-1, who is unaffected, is a carrier?", right="2/3",
         wrong=[("1/2", "Of the four equally likely outcomes, one (affected) is ruled out because he is unaffected. Two of the remaining three are carriers."),
                ("1/4", "1/4 is the chance a child of two carriers is affected, not the chance an unaffected child is a carrier."),
                ("1", "He could also be homozygous for the normal allele (1 of the 3 remaining outcomes).")],
         e=["I-1 × I-2: both carriers (Aa × Aa) → AA : Aa : aa = 1 : 2 : 1.", "II-1 is not aa, so P(Aa) = 2/(1 + 2) = 2/3."], k=2),
    dict(q="How can III-2 have CF when his mother, II-4, tested negative for F508del?", right="II-4 carries a different <i>CFTR</i> mutation",
         wrong=[("CF is dominant in this family", "III-2's sister, III-1, has a carrier parent on each side and is unaffected; the pattern is recessive."),
                ("III-2 inherited both F508del alleles from II-3", "Each parent passes only one allele. Table 1 shows III-2 has one copy of F508del."),
                ("The test is always wrong in women", "The test detects F508del reliably. It just doesn't look for rarer mutations.")],
         e=["III-2 has one F508del (from II-3) but still has CF.", "His other allele must carry a different mutation, inherited from II-4, that the test didn't screen for."], k=4),
    dict(q="If CF affects 1 in 2500 births, about what fraction of the population are carriers?", right="About 1 in 25",
         wrong=[("About 1 in 50", "1/50 is <i>q</i>, the allele frequency. Carriers are 2<i>pq</i> ≈ 2 × 1/50."),
                ("About 1 in 2500", "That is the frequency of affected people (<i>q</i><sup>2</sup>), not carriers."),
                ("About 1 in 5", "This overestimates. 2<i>pq</i> ≈ 2 × 0.98 × 0.02 ≈ 0.04.")],
         e=["<i>q</i><sup>2</sup> = 1/2500, so <i>q</i> = 1/50.", "2<i>pq</i> ≈ 2 × (49/50) × (1/50) ≈ 1/25."], k=2),
    dict(q="II-3 and II-4 plan another child. What is the probability that this child will have CF?", right="1/4",
         wrong=[("1/2", "Each parent is a carrier, so each passes the mutant allele with probability 1/2: 1/2 × 1/2."),
                ("0", "Their son III-2 has CF, which proves both parents are carriers."),
                ("1/8", "Each child is independent. The earlier affected child doesn't change the 1/4 risk.")],
         e=["III-2's diagnosis shows both II-3 and II-4 are carriers.", "Carrier × carrier: P(affected) = 1/4 for each pregnancy."], k=2),
]))

# ---------------------------------------------------------------- hemophilia A (X-linked recessive)
hm = {"a": (1, 2.5, "M", "U"), "b": (1, 4.5, "F", "U"),
      "c": (2, 0.5, "M", "U"), "d": (2, 1.5, "F", "U"), "e": (2, 3, "M", "A"), "f": (2, 5, "F", "U"), "g": (2, 6, "M", "U"),
      "h": (3, 0.5, "M", "A"), "i": (3, 1.5, "F", "U"), "j": (3, 5, "M", "U"), "k": (3, 6, "F", "U")}
P.append(passage("bios-02", "bb", "bio", 12, "Hemophilia in Three Generations", [
    "Hemophilia A is a bleeding disorder caused by mutations in the gene for clotting factor VIII, which lies on the X chromosome. Males have only one X chromosome, so a single mutant allele causes disease. Females with one mutant allele are usually carriers who have about half the normal factor VIII level and few symptoms.",
    pedigree("Figure 1 Pedigree of a family with hemophilia A", hm, couples=[("a", "b"), ("c", "d"), ("f", "g")],
             families=[(("a", "b"), ["d", "e", "f"]), (("c", "d"), ["h", "i"]), (("f", "g"), ["j", "k"])], w=440),
    "In a pedigree, squares are males, circles are females, and filled symbols are affected people. A horizontal line joins two parents, and a vertical line drops to their children. People are numbered left to right in each generation, so II-3 is the third person in generation II.",
    "A hematologist measured factor VIII activity in several family members (Table 1). Activity is reported as a percentage of the average in healthy people. Because one X chromosome is randomly inactivated in each cell of a female's body, carriers' levels vary widely, and some overlap with the normal range.",
    table("Table 1 Factor VIII activity (% of normal)", ["Person", "Factor VIII (%)"], [["II-3", "2"], ["II-2", "46"], ["III-1", "3"], ["III-2", "52"], ["II-4", "95"], ["Normal range", "50–150"]]),
    "Queen Victoria of England was a carrier of hemophilia B, a related X-linked clotting disorder, and passed it into several royal families of Europe through her daughters. Patterns like this, in which affected men are linked through unaffected women, are typical of X-linked recessive traits.",
    "Today, carrier status is usually confirmed by sequencing the factor VIII gene. Affected males are treated with infusions of factor VIII, either purified from donated plasma or made with recombinant DNA technology.",
], [
    dict(q="Which observation in Figure 1 best supports X-linked recessive inheritance?", right="Affected males have unaffected mothers",
         wrong=[("The disorder appears in every generation", "It skips generation I and appears through unaffected females, typical of recessive inheritance."),
                ("An affected father passes it on to his son", "No affected father appears in the pedigree. Male-to-male transmission would rule out X-linkage."),
                ("Affected females outnumber affected males", "No females are affected here.")],
         e=["II-3 and III-1 are affected males whose mothers (I-2 and II-2) are unaffected.", "Unaffected carrier mothers passing the trait to sons fits X-linked recessive."], k=4),
    dict(q="What is the genotype of I-2?", right="X<sup>H</sup>X<sup>h</sup>", wrong=[("X<sup>H</sup>X<sup>H</sup>", "Her son II-3 is affected and got his only X from her."),
                                                                                         ("X<sup>h</sup>X<sup>h</sup>", "She would be affected (very low factor VIII)."),
                                                                                         ("X<sup>h</sup>Y", "I-2 is female, so she has two X chromosomes.")],
         e=["An affected son (X<sup>h</sup>Y) gets his X from his mother.", "I-2 is unaffected, so she must be a carrier, X<sup>H</sup>X<sup>h</sup>."], k=2),
    dict(q="Is II-4's factor VIII level consistent with being a carrier?", right="Unlikely, but still possible",
         wrong=[("Yes; it proves she is a carrier", "95% is near the middle of the normal range, not the reduced level typical of carriers."),
                ("No; it proves she is not a carrier", "Because of random X inactivation, some carriers have normal levels. Gene testing is needed."),
                ("No; it shows she is affected", "Affected people have levels far below normal, like 2–3%.")],
         e=["II-4's level (95%) is in the normal range.", "Carriers usually have about 50%, but random X inactivation means a normal level can't rule out carrier status."], k=4),
    dict(q="Before any testing, what is the probability that II-4 is a carrier?", right="1/2",
         wrong=[("1/4", "This multiplies by the chance of having a daughter. II-4 is already known to be a daughter."),
                ("2/3", "That reasoning applies to unaffected siblings in autosomal recessive families."),
                ("0", "Her mother is a carrier and could have passed either X.")],
         e=["I-2 is X<sup>H</sup>X<sup>h</sup>, so each daughter gets X<sup>h</sup> with probability 1/2.", "II-4's father gave her X<sup>H</sup>, so she is a carrier with probability 1/2."], k=2),
    dict(q="If III-1 has children with a woman who is not a carrier, what will their children be?", right="Daughters carriers; sons unaffected",
         wrong=[("All sons affected; all daughters unaffected", "A father gives his Y, not his X, to his sons."),
                ("Half of all children affected", "None will be affected: daughters get one normal X from their mother."),
                ("All of their children affected", "Children need X<sup>h</sup> from both parents (daughters) or from their mother (sons) to be affected.")],
         e=["Father X<sup>h</sup>Y × mother X<sup>H</sup>X<sup>H</sup>.", "Daughters: X<sup>H</sup>X<sup>h</sup> (carriers). Sons: X<sup>H</sup>Y (unaffected)."], k=2),
]))

# ---------------------------------------------------------------- Huntington disease (autosomal dominant, anticipation)
hd = {"a": (1, 2.5, "M", "A"), "b": (1, 4, "F", "U"),
      "c": (2, 0.5, "M", "U"), "d": (2, 1.5, "F", "A"), "e": (2, 3.5, "M", "U"), "f": (2, 5, "M", "A"), "g": (2, 6, "F", "U"),
      "h": (3, 0.5, "F", "U"), "i": (3, 1.5, "M", "P"), "j": (3, 5, "M", "A"), "k": (3, 6, "F", "U")}
cag = [["I-1", "42", "48"], ["II-2", "44", "41"], ["II-4", "45", "39"], ["III-2", "44", "untested (age 22)"], ["III-3", "53", "27"], ["II-3", "17", "unaffected"]]
P.append(passage("bios-03", "bb", "bio", 12, "Huntington Disease and Growing Repeats", [
    "Huntington disease (HD) is a neurodegenerative disorder that causes uncontrolled movements, mood changes and declining thinking. It is caused by an expanded run of CAG repeats in the <i>HTT</i> gene. Each CAG codes for glutamine, so the mutant protein carries an abnormally long polyglutamine tract that makes it misfold and clump inside neurons.",
    pedigree("Figure 1 Pedigree of a family with Huntington disease", hd, couples=[("c", "d"), ("a", "b"), ("f", "g")],
             families=[(("a", "b"), ["d", "e", "f"]), (("c", "d"), ["h", "i"]), (("f", "g"), ["j", "k"])], w=440),
    "The number of repeats predicts disease: 26 or fewer is normal; 27–35 is an intermediate range that does not cause HD but can expand in the next generation; 36–39 gives incomplete penetrance; and 40 or more almost always causes HD within a normal lifespan. Longer repeats tend to cause earlier onset. Repeats are unstable during sperm production, so they expand most often when the gene is passed from a father.",
    "A neurologist recorded the larger CAG repeat number and the age at first symptoms for family members (Table 1). III-2 is 22 years old and has no symptoms; he was tested at his own request after counseling.",
    table("Table 1 CAG repeat length and age of onset", ["Person", "CAG repeats (larger allele)", "Age at onset (years)"], cag),
    "A presymptomatic test, like the one III-2 chose, can tell a person whether they carry an expanded allele long before symptoms begin. Because there is no cure, guidelines call for counseling before and after testing.",
    "The tendency of a genetic disease to appear earlier or more severely in later generations is called anticipation.",
], [
    dict(q="Which observation rules out X-linked inheritance for HD in this family?", right="II-4 passed HD to his son III-3",
         wrong=[("I-1 passed HD to his daughter II-2", "An affected father passes his X to every daughter, so father-to-daughter fits X-linked dominant too."),
                ("Both males and females are affected", "X-linked dominant traits also affect both sexes."),
                ("HD appears in every generation", "X-linked dominant traits can also appear in every generation.")],
         e=["A father gives his Y chromosome, not his X, to his sons.", "Male-to-male transmission (II-4 → III-3) means the gene can't be on the X."], k=4),
    dict(q="What is the chance that a child of II-2 (a heterozygote) and an unaffected partner inherits the HD allele?", right="1/2",
         wrong=[("1/4", "That's the risk for a recessive trait when both parents are carriers."),
                ("1", "II-2 is heterozygous, so she passes the HD allele only half the time."),
                ("0", "Dominant alleles are passed on, even though symptoms start later in life.")],
         e=["Autosomal dominant: Hh × hh.", "Children: 1/2 Hh (will develop HD), 1/2 hh."], k=2),
    dict(q="What do the data for I-1, II-4 and III-3 in Table 1 show?", right="Repeats grew and onset came earlier",
         wrong=[("Repeats shrank and onset came later", "Repeats rose (42 → 45 → 53) and onset fell (48 → 39 → 27)."),
                ("Repeat length had no relation to onset", "Longer repeats went with earlier onset in each generation."),
                ("Onset depends only on the parent's sex", "All three were in a line through fathers, but the trend tracks repeat length.")],
         e=["CAG: 42 → 45 → 53. Onset: 48 → 39 → 27 years.", "This is anticipation, driven by repeat expansion through the male line."], k=4),
    dict(q="How should III-2's result (44 repeats) be interpreted?", right="He will very likely develop HD",
         wrong=[("He is a carrier who will not be affected", "HD is dominant. 44 repeats is in the range that almost always causes disease."),
                ("He is in the intermediate range", "Intermediate is 27–35. He has 44."),
                ("He has a normal allele", "A normal allele has 26 or fewer repeats.")],
         e=["≥ 40 repeats: nearly full penetrance.", "He has no symptoms yet because onset usually comes in adulthood. His symbol is marked with a question mark."], k=2),
    dict(q="II-3 has normal repeats, but a cousin from another branch of the family has 34 repeats on one allele. What is the main concern for his future children?", right="The allele may expand to 36 or more in them",
         wrong=[("He will develop HD in middle age", "34 is in the intermediate range, which doesn't cause HD."),
                ("His children will certainly develop HD", "Expansion isn't certain. Many intermediate alleles pass on unchanged."),
                ("His daughters, but not his sons, are at risk", "HD is autosomal, so sons and daughters share the same risk.")],
         e=["27–35 repeats don't cause disease but are unstable.", "In the next generation they can expand into the disease range, especially when passed from a father."], k=2),
]))

# ---------------------------------------------------------------- mitochondrial disease
mt = {"a": (1, 2, "M", "U"), "b": (1, 3.5, "F", "A"),
      "c": (2, 0.5, "F", "U"), "d": (2, 1.5, "M", "A"), "g": (2, 2.5, "M", "A"), "e": (2, 3.5, "F", "A"), "f": (2, 4.5, "M", "U"),
      "h": (3, 0.5, "M", "U"), "i": (3, 1.5, "F", "U"), "j": (3, 3.5, "M", "A"), "k": (3, 4.5, "F", "U")}
het = [["I-2", "blood", "62", "hearing loss, diabetes"], ["II-2", "blood", "81", "stroke-like episodes, muscle weakness"], ["II-4", "blood", "45", "mild hearing loss"],
       ["III-3", "blood", "88", "severe; seizures at age 9"], ["III-4", "blood", "30", "no symptoms yet"], ["II-1", "blood", "0", "none"]]
P.append(passage("bios-04", "bb", "bio", 12, "A Disease Passed Only Through Mothers", [
    "MELAS (mitochondrial encephalomyopathy, lactic acidosis and stroke-like episodes) is most often caused by a single base change in a mitochondrial tRNA gene. Mitochondria have their own small circular DNA (mtDNA), and each cell contains hundreds to thousands of copies. A zygote receives essentially all of its mitochondria from the egg; the few mitochondria carried by sperm are destroyed after fertilization.",
    pedigree("Figure 1 Pedigree of a family with MELAS", mt, couples=[("c", "d"), ("a", "b"), ("e", "f")],
             families=[(("a", "b"), ["d", "e", "g"]), (("c", "d"), ["h", "i"]), (("e", "f"), ["j", "k"])], w=440),
    "A cell can contain a mixture of normal and mutant mtDNA, a condition called heteroplasmy. When a cell divides, its mitochondria are distributed randomly between the daughter cells, so the fraction of mutant mtDNA can drift up or down between cells and between an egg cell and the next generation. Symptoms usually appear only when the mutant fraction in a tissue rises above a threshold, and tissues with high energy demand, such as brain and muscle, are affected most.",
    "Physicians measured the percentage of mutant mtDNA in blood samples from family members (Table 1). Because mutant mtDNA tends to be lost from blood cells over time, blood percentages can underestimate those in muscle.",
    table("Table 1 Mutant mtDNA (heteroplasmy) and symptoms", ["Person", "Tissue", "Mutant mtDNA (%)", "Symptoms"], het),
    "Because every child of an affected mother inherits some mutant mtDNA, but in an unpredictable amount, genetic counseling for mitochondrial disease is especially difficult.",
    "Patients with MELAS often have high blood lactate, because mitochondria with defective protein synthesis cannot carry out oxidative phosphorylation efficiently, and cells rely more on glycolysis.",
], [
    dict(q="Which feature of Figure 1 best supports mitochondrial inheritance?", right="Mothers pass it on; fathers don't",
         wrong=[("Only males are affected", "Females are affected too (I-2 and II-4)."),
                ("Two unaffected parents have an affected child", "No such couple appears in Figure 1."),
                ("Exactly half the children of each affected parent are affected", "All of I-2's children are affected, and none of II-2's are.")],
         e=["All of I-2's children are affected, and II-4 passed the mutation to both of hers.", "None of II-2's children are affected, even though he is affected: fathers don't transmit mtDNA."], k=4),
    dict(q="Why does II-2 not pass MELAS to his children?", right="Sperm mitochondria are destroyed",
         wrong=[("The mutation is on his Y chromosome", "The mutation is in mtDNA, not in nuclear chromosomes."),
                ("He is only a carrier of the mutation", "Table 1 shows he has 81% mutant mtDNA and serious symptoms."),
                ("MELAS is recessive in males", "Mitochondrial traits don't follow dominant or recessive rules. They follow the mother.")],
         e=["A zygote's mitochondria come from the egg.", "Paternal mitochondria are eliminated, so a father's mtDNA isn't inherited."], k=1),
    dict(q="Why do siblings III-3 and III-4, with the same mother, differ so much in severity?", right="They got different mutant fractions",
         wrong=[("They have different nuclear genes for MELAS", "MELAS here is caused by an mtDNA mutation, and both share the same maternal mtDNA source."),
                ("Only III-3 inherited the mutation", "III-4 also carries mutant mtDNA (30%)."),
                ("Males are always more severely affected", "Severity follows the mutant fraction, not sex. II-4, a female, has milder disease than her brother II-2.")],
         e=["Mitochondria are divided randomly when egg cells form.", "III-3 received 88% mutant mtDNA, III-4 only 30%, so their severity differs."], k=4),
    dict(q="According to Table 1, which statement about the threshold for symptoms is best supported?", right="Symptoms are mild or absent below about 50%",
         wrong=[("Any amount of mutant mtDNA causes severe disease", "III-4 (30%) has no symptoms, and II-4 (45%) has only mild hearing loss."),
                ("Severity decreases as the mutant fraction rises", "The opposite: III-3 (88%) and II-2 (81%) are most severe."),
                ("Blood percentages exactly match those in muscle", "The passage says blood can underestimate the muscle percentage.")],
         e=["≤ 45%: none or mild. 62%: moderate. ≥ 81%: severe.", "This fits a threshold effect around 50–60% in blood."], k=4),
    dict(q="A doctor suspects III-4's blood value (30%) underestimates her true risk. Which test would best address this?", right="Test a muscle biopsy",
         wrong=[("Repeat the blood test in 10 years", "Blood levels tend to fall over time, so a later blood test would be even less reliable."),
                ("Sequence her nuclear <i>HTT</i> gene", "<i>HTT</i> is the Huntington gene and isn't related to MELAS."),
                ("Test her father's blood for the mutation", "Her father doesn't transmit mtDNA, so his results don't predict hers.")],
         e=["Muscle has high energy demand and keeps mutant mtDNA better than blood.", "A muscle measurement gives a better estimate of risk."], k=3),
]))
